package com.stormreach.sim;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * Layout of the Hollow Labyrinth: a large grid maze generated by a randomized depth-first search (which gives
 * long winding corridors and many dead ends), with some extra walls removed to create loops, four themed
 * quadrants, three key vaults in the outer corners and a sealed treasure chamber in the centre.
 */
public final class MazeLayout {
    public static final int N = 1, E = 2, S = 4, W = 8;
    public enum CellType { CORRIDOR, ROOM, KEY_VAULT, TREASURE, ENTRANCE }

    public final int size;
    /** Open sides per cell (bit set = passage). */
    public final int[] open;
    public final CellType[] type;
    public final int[] section; // 0..3 quadrant theme
    public final List<int[]> keyVaults = new ArrayList<>();
    public final List<int[]> lockerSpots = new ArrayList<>();
    public final int entranceX, entranceZ;
    public final int treasureMin, treasureMax;

    public MazeLayout(int size, long seed) {
        if (size < 9) throw new IllegalArgumentException("maze too small");
        this.size = size;
        this.open = new int[size * size];
        this.type = new CellType[size * size];
        this.section = new int[size * size];
        Random random = new Random(seed);
        int c = size / 2;
        treasureMin = c - 1;
        treasureMax = c + 1;
        for (int z = 0; z < size; z++)
            for (int x = 0; x < size; x++) {
                type[i(x, z)] = CellType.CORRIDOR;
                section[i(x, z)] = (x < c ? 0 : 1) + (z < c ? 0 : 2);
            }
        // carve the maze with an iterative depth-first search, skipping the treasure block
        boolean[] seen = new boolean[size * size];
        for (int z = treasureMin; z <= treasureMax; z++) for (int x = treasureMin; x <= treasureMax; x++) seen[i(x, z)] = true;
        ArrayDeque<int[]> stack = new ArrayDeque<>();
        stack.push(new int[]{0, 0});
        seen[0] = true;
        int[][] dirs = {{0, -1, N, S}, {1, 0, E, W}, {0, 1, S, N}, {-1, 0, W, E}};
        while (!stack.isEmpty()) {
            int[] cur = stack.peek();
            List<int[]> options = new ArrayList<>();
            for (int[] d : dirs) {
                int nx = cur[0] + d[0], nz = cur[1] + d[1];
                if (in(nx, nz) && !seen[i(nx, nz)]) options.add(d);
            }
            if (options.isEmpty()) { stack.pop(); continue; }
            int[] d = options.get(random.nextInt(options.size()));
            int nx = cur[0] + d[0], nz = cur[1] + d[1];
            open[i(cur[0], cur[1])] |= d[2];
            open[i(nx, nz)] |= d[3];
            seen[i(nx, nz)] = true;
            stack.push(new int[]{nx, nz});
        }
        // loops: knock out ~8% of remaining internal walls so the guardian (and you) have more than one way round
        for (int z = 0; z < size; z++)
            for (int x = 0; x < size; x++) {
                if (isTreasure(x, z)) continue;
                if (x + 1 < size && !isTreasure(x + 1, z) && (open[i(x, z)] & E) == 0 && random.nextDouble() < 0.08) link(x, z, x + 1, z, E, W);
                if (z + 1 < size && !isTreasure(x, z + 1) && (open[i(x, z)] & S) == 0 && random.nextDouble() < 0.08) link(x, z, x, z + 1, S, N);
            }
        // treasure chamber: fully open inside, one sealed door on the north side
        for (int z = treasureMin; z <= treasureMax; z++)
            for (int x = treasureMin; x <= treasureMax; x++) {
                type[i(x, z)] = CellType.TREASURE;
                if (x < treasureMax) link(x, z, x + 1, z, E, W);
                if (z < treasureMax) link(x, z, x, z + 1, S, N);
            }
        link(c, treasureMin, c, treasureMin - 1, N, S);
        // key vaults in three corners, the fourth corner holds the entrance stairway
        int[][] corners = {{size - 1, 0}, {0, size - 1}, {size - 1, size - 1}};
        for (int[] k : corners) {
            type[i(k[0], k[1])] = CellType.KEY_VAULT;
            keyVaults.add(k);
        }
        entranceX = 0;
        entranceZ = 0;
        type[i(0, 0)] = CellType.ENTRANCE;
        // a few rooms and hiding lockers: lockers go in dead ends and every few corridor cells
        for (int z = 0; z < size; z++)
            for (int x = 0; x < size; x++) {
                if (type[i(x, z)] != CellType.CORRIDOR) continue;
                int exits = Integer.bitCount(open[i(x, z)]);
                if (exits >= 3 && random.nextDouble() < 0.12) type[i(x, z)] = CellType.ROOM;
                else if (exits == 1 && random.nextDouble() < 0.35) lockerSpots.add(new int[]{x, z});
                else if (exits == 2 && random.nextDouble() < 0.03) lockerSpots.add(new int[]{x, z});
            }
    }

    private void link(int x, int z, int nx, int nz, int a, int b) {
        open[i(x, z)] |= a;
        open[i(nx, nz)] |= b;
    }

    public boolean isTreasure(int x, int z) {
        return x >= treasureMin && x <= treasureMax && z >= treasureMin && z <= treasureMax;
    }

    public int i(int x, int z) {
        return z * size + x;
    }

    public boolean in(int x, int z) {
        return x >= 0 && z >= 0 && x < size && z < size;
    }

    public int openAt(int x, int z) {
        return open[i(x, z)];
    }

    public CellType typeAt(int x, int z) {
        return type[i(x, z)];
    }

    public int deadEnds() {
        int n = 0;
        for (int v : open) if (Integer.bitCount(v) == 1) n++;
        return n;
    }

    /** Number of cells reachable from the entrance by following passages. */
    public int reachableFromEntrance() {
        boolean[] seen = new boolean[size * size];
        ArrayDeque<int[]> q = new ArrayDeque<>();
        q.add(new int[]{entranceX, entranceZ});
        seen[i(entranceX, entranceZ)] = true;
        int count = 0;
        int[][] dirs = {{0, -1, N}, {1, 0, E}, {0, 1, S}, {-1, 0, W}};
        while (!q.isEmpty()) {
            int[] cur = q.poll();
            count++;
            for (int[] d : dirs) {
                if ((open[i(cur[0], cur[1])] & d[2]) == 0) continue;
                int nx = cur[0] + d[0], nz = cur[1] + d[1];
                if (in(nx, nz) && !seen[i(nx, nz)]) { seen[i(nx, nz)] = true; q.add(new int[]{nx, nz}); }
            }
        }
        return count;
    }

    /** Passages must be symmetric: if a cell opens east, its neighbour opens west. */
    public boolean consistent() {
        for (int z = 0; z < size; z++)
            for (int x = 0; x < size; x++) {
                int o = open[i(x, z)];
                if ((o & E) != 0 && (x + 1 >= size || (open[i(x + 1, z)] & W) == 0)) return false;
                if ((o & S) != 0 && (z + 1 >= size || (open[i(x, z + 1)] & N) == 0)) return false;
                if ((o & W) != 0 && (x == 0 || (open[i(x - 1, z)] & E) == 0)) return false;
                if ((o & N) != 0 && (z == 0 || (open[i(x, z - 1)] & S) == 0)) return false;
            }
        return true;
    }
}
